package com.governai.decision;import java.math.BigDecimal;import java.time.OffsetDateTime;import java.util.UUID;public record EvidenceResponse(UUID id,UUID decisionRequestId,EvidenceSource sourceType,UUID policySectionId,UUID regulatorySectionId,UUID sourceDocumentId,String sourceDocumentTitle,String sourceSectionNumber,String sourceSectionHeading,String sourceTitle,String sectionReference,String evidenceText,BigDecimal relevanceScore,EvidenceType evidenceType,OffsetDateTime createdAt){public static EvidenceResponse from(RetrievedEvidence e){return new EvidenceResponse(e.getId(),e.getDecisionRequestId(),e.getSourceType(),e.getPolicySectionId(),e.getRegulatorySectionId(),null,null,null,null,e.getSourceTitle(),e.getSectionReference(),e.getEvidenceText(),e.getRelevanceScore(),e.getEvidenceType(),e.getCreatedAt());}public static EvidenceResponse withProvenance(RetrievedEvidence e,UUID documentId,String documentTitle,String sectionNumber,String sectionHeading){return new EvidenceResponse(e.getId(),e.getDecisionRequestId(),e.getSourceType(),e.getPolicySectionId(),e.getRegulatorySectionId(),documentId,documentTitle,sectionNumber,sectionHeading,e.getSourceTitle(),e.getSectionReference(),e.getEvidenceText(),e.getRelevanceScore(),e.getEvidenceType(),e.getCreatedAt());}}
